import { Provider } from '@angular/core';
import { LucideDynamicIcon, provideLucideIcons } from '@lucide/angular';
import { KIT_ICONS } from './icons.generated';

/**
 * The kit's icons (design/vendor/lucide = @lucide/angular 1.49.0): `<svg lucideIcon="database" class="gw-icon">`
 * replaces the kit's `<i class="gw-icon" data-lucide="database">`. Only the kit's 171 names are registered
 * (generated by ui/scripts/kit-icons.mjs), aliases included, so the kit's spelling (`trash-2`, `filter`, `history`)
 * keeps working. Icons are decorative (`aria-hidden`); meaning is in the text next to them.
 */
export function provideKitIcons(): Provider {
  return provideLucideIcons(...KIT_ICONS);
}

/** The icon component, under the kit's name. */
export { LucideDynamicIcon as GwIcon };
